    religion_composition: "仏教、道教、民間信仰が広く見られ、カトリックを中心とするキリスト教の歴史もあります。宗教帰属の公的な統一比率が限られるため、単一の数値は表示していません。",
    society: "中国文化を基盤に、長いポルトガル統治の影響が建築、宗教、言語、食文化に残っています。人口密度が高く、観光客や域外労働者の存在も地域社会と消費市場に影響します。",
    industries: "観光、統合型リゾート、ホテル、外食、小売、金融、建設が主要分野です。食品は輸入依存度が高く、ホテル・飲食店向けの業務用需要が重要です。",
    food: "広東料理を基盤に、ポルトガル料理と中国料理が融合したマカオ料理があります。米、麺、豚肉、魚介を使い、エッグタルトなど観光と結び付いた食品も有名です。",
    japan_relation: "日本とは観光、食品、外食、小売を中心に交流があります。日本産食品や日本料理はホテル・飲食市場でも扱われています。",
    history: "16世紀半ばからポルトガル人の居留が進み、東西交易の拠点となりました。1887年以降ポルトガル統治が制度化され、1999年に中国へ返還されました。返還後は一国二制度の下で特別行政区となっています。",
