    religion_composition: "キリスト教62％、無宗教29％、その他の宗教7％（2023〜2024年調査）。キリスト教にはプロテスタント、カトリック、その他の教派が含まれ、宗教構成には州・地域による差があります。",
    society: "信教の自由が憲法で保障されています。キリスト教に加え、ユダヤ教、イスラム教、ヒンドゥー教、仏教など多様な宗教的背景を持つ人々が暮らしています。",
    industries: "工業全般、農林業、IT・情報通信、金融・保険、不動産、医療、物流、小売、外食、各種サービスが主要分野です。食品市場は大規模で、多民族市場、健康志向、利便性、価格、地域性が同時に存在します。",
    food: "小麦、トウモロコシ、肉類、乳製品などを使う食事に加え、移民文化を背景に世界各地の料理が日常化しています。外食、スーパーマーケット、量販店、宅配、冷凍・調理済み食品の市場が発達しています。",
    japan_relation: "日本と米国は同盟関係にあり、貿易・投資でも結び付きが強い関係です。日本食レストラン、食品輸出、日系小売・メーカー、在留邦人など、日本関連の市場情報が多い国です。",
    history: "1776年に独立を宣言し、1787年制定の合衆国憲法を基礎に連邦国家が形成されました。19世紀には領土拡大と工業化が進む一方、南北戦争を経験しました。20世紀には世界有数の経済・軍事大国となり、第二次世界大戦後は国際秩序、金融、科学技術、文化に大きな影響を与えています。",
