    industries: "観光、食品、医薬、機械、造船、木材、情報通信が主要分野です。アドリア海沿岸の宿泊・外食需要が大きい国です。",
    food: "沿岸部では魚介、オリーブ油、パスタ、内陸部では肉、パン、乳製品を多く使います。地中海、中欧、バルカンの影響があります。",
