    religion_composition: "ロシア正教が最大の宗教的背景で、イスラム教が主要な少数宗教です。仏教、ユダヤ教、他のキリスト教、無宗教もあり、正確な比率は調査方法で大きく異なります。",
    society: "ロシア人が多数を占める多民族国家で、タタール人など多数の民族共和国・地域があります。人口動態、地域格差、政治的自由、戦争による人的・経済的影響が課題です。",
    industries: "石油・天然ガス、鉱業、鉄鋼、化学、軍需・航空宇宙、機械、穀物、林業、情報技術が主要分野です。制裁と貿易先の変化で供給網が再編されています。",
    food: "パン、じゃがいも、穀物、肉、魚、乳製品を使い、スープ、ピロシキ、ペリメニ、保存食が知られます。広大な国土で地域差があります。",
    japan_relation: "日本とは隣国として漁業、エネルギー、人的交流の歴史がありますが、北方領土問題とウクライナ侵略を受けた制裁により関係は厳しい状態です。",
    history: "キエフ・ルーシ、モスクワ大公国を経てロシア帝国が成立しました。1917年革命後はソ連の中心となり、1991年のソ連解体後にロシア連邦が成立しました。2022年にウクライナへの全面侵略を開始し、2026年7月時点でも戦争が続いています。",
