    society: "ウクライナ人が多数を占め、クリミア・タタール人、ロシア人など多様な住民が暮らします。戦争により国内避難、国外避難、家族分離、インフラ被害が続いています。",
    industries: "農業・穀物、食品、鉄鋼、鉱業、機械、航空宇宙、情報技術が主要分野です。戦争下では防衛産業、エネルギー復旧、物流再建の比重が高まっています。",
    food: "小麦、じゃがいも、ビーツ、キャベツ、豚肉、乳製品を使い、ボルシチ、ヴァレーニキ、パンが知られます。黒土地帯は世界有数の穀倉地帯です。",
