    religion_composition: "キリスト教徒が約7割、イスラム教徒が約2割で、伝統宗教もあります。北部ではイスラム教徒、南部・西部ではキリスト教徒の割合が高い傾向です。",
    society: "250以上の民族・言語集団が暮らし、フランス語圏と英語圏を持ちます。英語圏地域の対立、北部の治安、若年雇用、地域格差が課題です。",
    industries: "石油・天然ガス、カカオ、コーヒー、綿花、バナナ、木材、食品、アルミ、港湾・物流が主要分野です。",
    food: "キャッサバ、プランテン、とうもろこし、米、豆、魚、肉、ピーナツを使います。地域ごとに中央・西・サヘルの食文化が見られます。",
    japan_relation: "日本は農業、保健、教育、水産、森林保全、人材育成で協力しています。",
    history: "沿岸交易と内陸諸王国の歴史を持ち、ドイツ植民地の後、第一次世界大戦後にフランス領と英国領へ分割されました。1960年の仏領地域独立と翌年の英領南部統合により現在の国家が形成されました。",
