    religion_composition: "キリスト教徒が人口の8割以上を占め、伝統的アフリカ宗教、イスラム教、ヒンドゥー教、ユダヤ教、無宗教などもあります。宗教構成は民族・地域により多様です。",
    society: "多民族・多言語社会で、アパルトヘイト撤廃後に法的平等が確立されました。一方、所得・資産格差、失業、治安、電力、行政サービスが大きな課題です。",
    industries: "金、白金、鉄鉱石、石炭、自動車、機械、化学、食品、農業、金融、小売、通信、観光が主要分野です。大手企業と近代流通が周辺国にも展開しています。",
