    history: "ダホメ王国と沿岸交易の歴史を持ち、19世紀末にフランス植民地となりました。1960年にダホメとして独立し、1975年にベナンへ改称しました。社会主義体制を経て1990年代に複数政党制へ移行しました。",
    sources: [["外務省『ベナン共和国基礎データ』", "https://www.mofa.go.jp/mofaj/area/benin/data.html"]]
