    updated: "2026-07-16", overview: "パラオは西太平洋の島国で、豊かな海洋生態系を生かした観光と漁業が重要です。米国との自由連合、公共部門、海外援助も経済を支えています。",
    facts: [["首都", "マルキョク"],["公用語", "パラオ語、英語"],["通貨", "米ドル（USD）"],["政治体制", "共和制・大統領制、米国との自由連合"]],
